    '--dshui-text-primary': { light: '#10233d', dark: '#eef5ff' },
    '--dshui-text-secondary': { light: '#526a86', dark: '#aebdd0' },
    '--dshui-text-tertiary': { light: '#7186a0', dark: '#7f91a8' },
    '--dshui-text-caption': { light: '#8799ae', dark: '#62758d' },
    '--dshui-border-1': { light: 'rgba(76, 105, 142, 0.10)', dark: 'rgba(153, 190, 232, 0.08)' },
    '--dshui-border-2': { light: 'rgba(76, 105, 142, 0.15)', dark: 'rgba(153, 190, 232, 0.13)' },
    '--dshui-border-3': { light: 'rgba(76, 105, 142, 0.21)', dark: 'rgba(153, 190, 232, 0.18)' },
    '--dshui-border-4': { light: 'rgba(66, 96, 134, 0.28)', dark: 'rgba(174, 207, 243, 0.24)' },
